import {GEAR,STYLES,SUPPLIES,RECIPES} from './data.js';
import {rodArt} from './angling-visuals.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=(a,id)=>a.find(x=>x.id===id),num=(n,d=0)=>new Intl.NumberFormat('nl-NL',{maximumFractionDigits:d,minimumFractionDigits:d}).format(n||0),pct=(n,d=1)=>num(n*100,d)+'%',euro=n=>'€ '+num(n,2),kg=n=>num(n,n<1?2:1)+' kg';
export const PHASES={broken:'HENGEL GEBROKEN',waiting:'WACHT OP EEN BEET',nibble:'VOORBEET · NOG WACHTEN',bite:'BEET! SLA NU AAN',rescue:'ASSISTENT MIST — RED DE BEET',landed:'MOOI GELAND',missed:'BEET GEMIST',recovering:'TE VROEG · OPNIEUW INLEGGEN'};
export function biteDeck(game){const s=game.state,session=s.session,l=session?.loadout||game.loadout;return `<section class="panel angling-panel"><div class="panel-head"><div><span class="eyebrow">DE BEET VERTELT HET VERHAAL</span><h2>Live aan je lijnen</h2></div><button class="button small" data-action="toggle-audio"><span class="sound-status">Geluid inschakelen</span></button></div><div class="angling-toolbar"><div class="angling-modes" aria-label="Visstand"><button data-fishing-mode="idle" class="${s.settings.fishingMode==='idle'?'active':''}">Ontspannen</button><button data-fishing-mode="active" class="${s.settings.fishingMode==='active'?'active':''}">Actief opletten</button></div><span>Zelf aanslaan: +${num((game.manualXpMultiplier(false)-1)*100)}% XP & sneller opnieuw vissen</span></div><p class="angling-instruction">Korte tikjes zijn voorbeten. Wacht op doorbuigen, een aflopende spoel of een duikende dobber. Druk op de hengelknop of toets 1–6; spatie kiest een beet die nu aandacht vraagt.</p><div class="bite-stations count-${l.rods.length}">${l.rods.map((r,i)=>`<article class="bite-station" data-live-rod="${i}" data-phase="waiting"><div class="station-heading"><span class="station-number">0${i+1}</span><div><h3>${esc(get(GEAR,r.rod)?.name)}</h3><small>${esc(r.indicator?get(GEAR,r.indicator)?.name:r.style==='karper'?'Vrijloopspoel · standaard':r.style==='feeder'?'Quivertop · standaard':r.style==='dobber'?'Klassieke dobber':'Molenratel')}</small></div><kbd>${i+1}</kbd></div><button class="rod-monitor" data-strike="${i}" disabled aria-label="Aanslaan op hengel ${i+1}">${rodArt(r,{index:i})}</button><div class="station-signal"><i></i><strong data-signal-text="${i}">WACHT OP EEN BEET</strong><span data-signal-time="${i}"></span></div><div class="strike-window"><i data-bite-progress="${i}"></i></div><button class="strike-button" data-strike="${i}" disabled><span data-strike-label="${i}">${session?'Wachten op een beet':'Start eerst je sessie'}</span><span>↗</span></button><p class="station-outcome" data-outcome="${i}">${session?'Je assistent vist automatisch mee.':'Hier lees je straks de beet van deze hengel.'}</p></article>`).join('')}</div><div class="angling-session-stats"><div><b data-angling-stat="manualCaught">${session?.manualCaught||0}</b><span>ZELF GEVANGEN</span></div><div><b data-angling-stat="autoCaught">${session?.autoCaught||0}</b><span>DOOR ASSISTENT</span></div><div><b data-angling-stat="rescuedBites">${session?.rescuedBites||0}</b><span>BETEN GERED</span></div><div><b data-angling-stat="missedBites">${session?.missedBites||0}</b><span>BETEN GEMIST</span></div></div><p class="angling-mode-note" id="angling-mode-note">Ook in idle kun je op tijd zelf aanslaan. De assistent blijft werken als je weg bent.</p></section>`;}
export function rodStudio(game,r,index){const ind=get(GEAR,r.indicator),line=get(GEAR,r.line),hook=get(GEAR,r.hook);const components=[['rod','Hengel',get(GEAR,r.rod)?.name],['reel','Molen',get(GEAR,r.reel)?.name],['line','Lijn',line?.name],['hook','Haak',hook?.name],['bait','Aas',get(SUPPLIES,r.bait)?.name],['indicator','Beetmelder',ind?.name||'Standaardsignaal']];return `<section class="rod-studio" data-editor-studio="${index}"><div class="studio-heading"><span>JOUW ${get(STYLES,r.style).name.toUpperCase()}SET IN BEELD</span><button class="button small" data-preview-bite="${index}">Beetvoorbeeld ▷</button></div>${rodArt(r,{index,editor:true})}<div class="studio-components">${components.map(([id,n,value])=>`<button data-focus-part="${id}" data-focus-index="${index}"><span>${n}</span><strong>${esc(value)}</strong></button>`).join('')}</div><div class="studio-rig-facts"><span>Haak ${hook?.min||0}–${hook?.max||0} kg</span><span>Veilige setgrens ${kg((line?.strength||0)*Math.sqrt(get(GEAR,r.rod)?.power||1)*1.5)}</span><span>Assistent ${pct(game.autoChance(r),0)}</span><span>Aanslagtijd ${num(game.biteWindow(r),1)}s</span></div><p>Klik een onderdeel in de tekening of de kaartjes om het hieronder aan te passen. Een beetvoorbeeld verandert je sessie niet.</p></section>`;}
export function forecastPanel(game,{loadout,water,source='plan',rod='all'}={}){
 const allLoadout=loadout||game.loadout,w=water||game.water,l=rod==='all'?allLoadout:{...allLoadout,rods:[allLoadout.rods[Number(rod)]||allLoadout.rods[0]]},f=game.forecast(l,w),gain=f.auto.catches?(f.manual.catches/f.auto.catches-1)*100:0;
 const context=source==='session'?'Lopende sessie':'Gekozen hengels';
 return `<section class="panel forecast-panel"><div class="panel-head"><div><span class="eyebrow">WEET WAT ER ONDER WATER GEBEURT</span><h2>Je vangstkansen uitgelegd</h2></div><span class="tag">${w.name}</span></div><div class="forecast-toolbar"><label>Berekening voor<select id="forecast-source" aria-label="Bron voor vangstkansen"><option value="plan" ${source==='plan'?'selected':''}>Gekozen hengels</option>${game.state.session?`<option value="session" ${source==='session'?'selected':''}>Lopende sessie · ${esc(game.state.session.loadout.name)}</option>`:''}</select></label><label>Hengel<select id="forecast-rod" aria-label="Hengel voor vangstkansen"><option value="all">Alle hengels samen</option>${allLoadout.rods.map((r,i)=>`<option value="${i}" ${String(rod)===String(i)?'selected':''}>${i+1} · ${get(STYLES,r.style).name}</option>`).join('')}</select></label><span>${context} · ${l.rods.length} hengel${l.rods.length>1?'s':''}</span></div><div class="forecast-summary"><div><span>AUTOMATISCH</span><b>${num(f.auto.catches,1)}<small>/uur</small></b><p>Inclusief gemiste aanslagen</p></div><div><span>ACTIEF AANSLAAN</span><b>${num(f.manual.catches,1)}<small>/uur</small></b><p class="lime-text">~${num(gain)}% meer bij tijdig reageren</p></div><div><span>VIS-XP PER UUR</span><b>${num(f.auto.xp)}<small>→ ${num(f.manual.xp)}</small></b><p>Automatisch → actief</p></div><div><span>BRUTO VISWAARDE</span><b>${euro(f.auto.value)}<small>/uur</small></b><p>Actief ~${euro(f.manual.value)} / uur</p></div></div><div class="forecast-bycatch"><span>BIJVANGST & LASTPAKKEN</span><strong data-bycatch-share>${pct(f.auto.catches?f.bycatchHour/f.auto.catches:0,1)}</strong><small>van je verwachte vangsten · al meegerekend in waarde en aantallen</small></div><div class="forecast-explainer">De actieve raming gaat uit van aanslaan op iedere echte beet na ongeveer <b>1,5 seconde</b>. Maten en soorten komen uit dit water, je aas, haakbereik en lijn/hengelkracht. Je visstijl is een doel, geen garantie: witvis kan op karperaas bijten en rivierkreeften kunnen aas vastpakken. Voorraad, opslagruimte, vispas- en voerkosten zijn niet in het uurtotaal verwerkt. De raming gaat uit van onbeschadigde hengels; overbelasting kan je sessie inkorten.</div><div class="forecast-section-heading"><h3>Welke vis kun je landen?</h3><span>Aandeel = aandeel in je verwachte automatische vangsten</span></div><div class="table-wrap"><table class="data-table species-forecast"><thead><tr><th>VISSOORT</th><th>AANDEEL VANGST</th><th>PER 100 WORPEN</th><th>LANDBARE MAAT</th><th>AUTO / ACTIEF PER UUR</th><th>WAAROM?</th></tr></thead><tbody>${f.rows.map(row=>{const chance=f.auto.casts?row.autoHour/f.auto.casts:0,viable=row.autoHour>0;return `<tr class="${viable?'':'unavailable-species'}"><td><strong>${row.name}</strong><small>In dit water ${kg(row.waterMin)}–${kg(row.waterMax)}</small></td><td><b>${pct(row.autoShare,1)}</b><div class="probability-track"><i style="width:${row.autoShare*100}%"></i></div></td><td>${num(chance*100,2)}</td><td>${viable?kg(row.min)+' – '+kg(row.max):'Niet landbaar'}</td><td><span>${num(row.autoHour,1)}</span><b class="active-rate"> / ${num(row.manualHour,1)}</b></td><td><details class="forecast-reasons"><summary>${viable?'Zo werkt je set':'Bekijk de beperking'}</summary>${row.byRod.map((rr,i)=>`<div><b>Hengel ${rod==='all'?i+1:Number(rod)+1} · ${get(STYLES,l.rods[i].style).name}</b>${rr.reasons.map(reason=>`<p>${esc(reason)}</p>`).join('')}</div>`).join('')}</details></td></tr>`;}).join('')}</tbody></table></div><div class="forecast-section-heading"><h3>Verdeling van het vangstgewicht</h3><span>Van de vissen die je automatisch landt</span></div><div class="weight-histogram" role="img" aria-label="Gewichtsklassen van verwachte vangsten">${f.bins.filter(b=>b.autoHour>0||b.manualHour>0).map(b=>{const share=f.auto.catches?b.autoHour/f.auto.catches:0,max=Math.max(...f.bins.map(b=>b.autoHour),.001);return `<div class="weight-bin"><b>${pct(share,1)}</b><div><i style="height:${Math.max(2,b.autoHour/max*100)}%"></i></div><span>${num(b.min,b.min<1?1:0)}–${num(b.max,b.max<1?1:0)}</span><small>kg</small></div>`;}).join('')||'<p class="subtle">Met deze combinatie is geen vis landbaar. Bekijk de beperkingen in de tabel.</p>'}</div><div class="forecast-section-heading"><h3>De stappen van een vangst</h3><span>Echte beet → soortselectie → passende maat → aanslag</span></div><div class="rod-explanations">${f.rods.map((r,i)=>`<article><span class="eyebrow">HENGEL ${rod==='all'?i+1:Number(rod)+1} · ${get(STYLES,r.rod.style).name.toUpperCase()}</span><div class="chance-steps"><div><b>${pct(r.biteChance,0)}</b><small>Echte beet/worp</small></div><i>→</i><div><b>${pct(r.fitProbability,0)}</b><small>Past bij haak & lijn</small></div><i>→</i><div><b>${pct(r.autoChance,0)}</b><small>Assistent reageert</small></div></div><p>Zelf aanslaan: <b>${pct(r.manualChance,1)}</b> landingskans op een passende beet. Beschikbare aanslagtijd: <b>${num(r.window,1)}s</b>. Assistent reageert na 3,2s. Een gemiste aanslag kun je tot het eind van dat venster redden.</p><details><summary>Bekijk beetbonussen en materiaalgrenzen</summary><div class="effect-list">${r.effects.filter(e=>e.value).map(e=>`<div><span>${e.name}</span><b>+${num(e.value*100,1)} procentpunt</b></div>`).join('')}<p>Beetkans maximaal 97%. Aasvoorkeur beïnvloedt de relatieve soortselectie apart van deze beetkans.</p><p>Interval zonder beetafhandeling: ${num(r.interval,1)}s. Haak ${get(GEAR,r.rod.hook).min}–${get(GEAR,r.rod.hook).max} kg. Lijn ${get(GEAR,r.rod.line).strength} kg × hengelfactor ${num(Math.sqrt(get(GEAR,r.rod.rod).power)*1.5,2)} (begrensd door de hengel) → veilige setgrens ${kg(r.strength)}.</p></div></details></article>`).join('')}</div><p class="forecast-footnote">Dit zijn verwachtingen van het spelmodel. Een individuele sessie kan hoger of lager uitvallen. Vis die niet bij je haak of veilige setgrens past, wordt ook bij snel aanslaan niet ineens landbaar.</p></section>`;
}
